import { MiniAppPerformanceRequiredSteps, MiniAppPerformanceErrors, MiniAppPerformanceErrorsDescription, MiniAppPerformanceSteps } from '../../constants/performance.js';

const getEmptyPerformanceStatsFields=e=>MiniAppPerformanceRequiredSteps.reduce((r,o)=>{if(!e[o]){r.push(o);}return r},[]);const isAllDataCollected=e=>MiniAppPerformanceRequiredSteps.every(r=>e[r]);const handlePerformanceStatsError=t=>{const n=getEmptyPerformanceStatsFields(t);const s={errorCode:MiniAppPerformanceErrors.Unknown};if(n.length>2){s.errorCode=MiniAppPerformanceErrors.Unknown;s.errorDescription=MiniAppPerformanceErrorsDescription.StorageTroubles;}else {switch(n[0]){case MiniAppPerformanceSteps.WebviewEndLoad:s.errorCode=MiniAppPerformanceErrors.Network;s.errorDescription=MiniAppPerformanceErrorsDescription.IframeNotLoad;break;case MiniAppPerformanceSteps.AppInit:case MiniAppPerformanceSteps.End:s.errorCode=MiniAppPerformanceErrors.UserCanceled;s.errorDescription=MiniAppPerformanceErrorsDescription.NotAppInit;break;default:s.errorCode=MiniAppPerformanceErrors.Unknown;s.errorDescription=MiniAppPerformanceErrorsDescription.StorageTroubles;}}return s};

export { getEmptyPerformanceStatsFields, handlePerformanceStatsError, isAllDataCollected };
